49	/**
50	 * An abstract reader context class for {@code HoodieFileGroupReader} to use, containing APIs for
51	 * engine-specific implementation on reading data files, getting field values from a record,
52	 * transforming a record, etc.
53	 * <p>
54	 * For each query engine, this class should be extended and plugged into {@code HoodieFileGroupReader}
55	 * to realize the file group reading.
56	 *
57	 * @param <T> The type of engine-specific record representation, e.g.,{@code InternalRow} in Spark
58	 *            and {@code RowData} in Flink.
59	 */
60	public abstract class HoodieReaderContext<T> {
61	  private final StorageConfiguration<?> storageConfiguration;
62	  private FileGroupReaderSchemaHandler<T> schemaHandler = null;
63	  private String tablePath = null;
64	  private String latestCommitTime = null;
65	  private Option<HoodieRecordMerger> recordMerger = null;
66	  private Boolean hasLogFiles = null;
67	  private Boolean hasBootstrapBaseFile = null;
68	  private Boolean needsBootstrapMerge = null;
69	  private Boolean shouldMergeUseRecordPosition = null;
70	
71	  // for encoding and decoding schemas to the spillable map
72	  private final LocalAvroSchemaCache localAvroSchemaCache = LocalAvroSchemaCache.getInstance();
73	
74	  protected HoodieReaderContext(StorageConfiguration<?> storageConfiguration) {
75	    this.storageConfiguration = storageConfiguration;
76	  }
77	
78	  // Getter and Setter for schemaHandler
