143	    return shouldMergeUseRecordPosition;
144	  }
145	
146	  public void setShouldMergeUseRecordPosition(boolean shouldMergeUseRecordPosition) {
147	    this.shouldMergeUseRecordPosition = shouldMergeUseRecordPosition;
148	  }
