48	public class HoodieFileGroupReaderTestHarness extends HoodieCommonTestHarness {
49	  protected static final String PARTITION_PATH = "any-partition-path";
50	  protected static final String FILE_ID = "any-file-1";
51	  // Set the key range for base file and log files.
52	  protected static List<HoodieFileSliceTestUtils.KeyRange> keyRanges;
