133	            shouldWritePositions.subList(0, numFiles),
134	            basePath,
135	            PARTITION_PATH,
136	            FILE_ID
137	        );
138	
139	    HoodieFileGroupReader<IndexedRecord> fileGroupReader =
140	        HoodieFileGroupReaderTestUtils.createFileGroupReader(
