43	/**
44	 * Factory help to create {@link org.apache.hudi.keygen.KeyGenerator}.
45	 * <p>
46	 * This factory will try {@link HoodieWriteConfig#KEYGENERATOR_CLASS_NAME} firstly, this ensures the class prop
47	 * will not be overwritten by {@link KeyGeneratorType}
48	 */
49	public class HoodieAvroKeyGeneratorFactory {
50	
51	  private static final Logger LOG = LoggerFactory.getLogger(HoodieAvroKeyGeneratorFactory.class);
52	
53	  public static KeyGenerator createKeyGenerator(TypedProperties props) throws IOException {
54	    // keyGenerator class name has higher priority
55	    KeyGenerator keyGenerator = KeyGenUtils.createKeyGeneratorByClassName(props);
56	    return Objects.isNull(keyGenerator) ? createAvroKeyGeneratorByType(props) : keyGenerator;
57	  }
58	
59	  public static KeyGenerator createAvroKeyGeneratorByType(TypedProperties props) throws IOException {
60	    // Use KeyGeneratorType.SIMPLE as default keyGeneratorType
61	    String keyGeneratorType =
62	        props.getString(HoodieWriteConfig.KEYGENERATOR_TYPE.key(), null);
63	
64	    if (StringUtils.isNullOrEmpty(keyGeneratorType)) {
65	      LOG.info("The value of {} is empty, using SIMPLE", HoodieWriteConfig.KEYGENERATOR_TYPE.key());
66	      keyGeneratorType = KeyGeneratorType.SIMPLE.name();
67	    }
68	
69	    KeyGeneratorType keyGeneratorTypeEnum;
70	    try {
71	      keyGeneratorTypeEnum = KeyGeneratorType.valueOf(keyGeneratorType.toUpperCase(Locale.ROOT));
72	    } catch (IllegalArgumentException e) {
73	      throw new HoodieKeyGeneratorException("Unsupported keyGenerator Type " + keyGeneratorType);
74	    }
75	
76	    BaseKeyGenerator keyGenerator = null;
77	
78	    switch (keyGeneratorTypeEnum) {
79	      case SIMPLE:
80	        keyGenerator = new SimpleAvroKeyGenerator(props);
81	        break;
82	      case COMPLEX:
83	        keyGenerator = new ComplexAvroKeyGenerator(props);
84	        break;
85	      case TIMESTAMP:
86	        keyGenerator = new TimestampBasedAvroKeyGenerator(props);
87	        break;
88	      case CUSTOM:
89	        keyGenerator = new CustomAvroKeyGenerator(props);
90	        break;
91	      case NON_PARTITION:
92	        keyGenerator = new NonpartitionedAvroKeyGenerator(props);
93	        break;
94	      case GLOBAL_DELETE:
95	        keyGenerator = new GlobalAvroDeleteKeyGenerator(props);
96	        break;
97	      default:
98	        throw new HoodieKeyGeneratorException("Unsupported keyGenerator Type " + keyGeneratorType);
99	    }
100	
101	    if (KeyGenUtils.isAutoGeneratedRecordKeysEnabled(props)) {
102	      return new AutoRecordGenWrapperAvroKeyGenerator(props, keyGenerator);
103	    } else {
104	      return keyGenerator;
105	    }
106	  }
107	
108	}
