public class HoodieAvroReaderContext extends HoodieReaderContext<IndexedRecord> {

  // Position of the "_hoodie_record_key" meta field in the ordered list of meta columns.
  private static final int RECORD_KEY_META_FIELD_POS =
      HOODIE_META_COLUMNS.indexOf(RECORD_KEY_METADATA_FIELD);

  private final boolean populateMetaFields;
  private final Option<BaseKeyGenerator> keyGeneratorOpt;
  private final String payloadClass;

  public HoodieAvroReaderContext(
      StorageConfiguration<?> storageConfiguration,
      HoodieTableConfig tableConfig) {
    super(storageConfiguration);
    this.populateMetaFields = tableConfig.populateMetaFields();
    this.payloadClass = tableConfig.getPayloadClass();
    if (populateMetaFields) {
      this.keyGeneratorOpt = Option.empty();
    } else {
      this.keyGeneratorOpt = Option.of(buildKeyGenerator(tableConfig));
    }
  }

  public HoodieAvroReaderContext(
